def make_snapshot(inputs):
    def blank(value):
        return value if value not in ('', 'null', None) else None
    def integer(value):
        return int(value) if blank(value) is not None else None
    def instant(value):
        return datetime.datetime.fromisoformat(value.replace('Z','+00:00'))
    records=[]
    for line in inputs['pods']['response']['stdout'].splitlines():
        a=line.split('\t')
        if a[0]=='POD':
            assert len(a)==9
