            row={'name':a[1],'uid':a[2],'createdAt':a[3],'deletionTimestamp':blank(a[4]),'nodeAssigned':node is not None,'nodeIdentitySha256':hashlib.sha256(node.encode()).hexdigest() if node else None,'nodeSelectorArchitecture':blank(a[6]),'phase':blank(a[7]),'scaleSetLabel':blank(a[8]),'owners':[],'conditions':[],'init':[],'containers':[]}
            uuid.UUID(row['uid'])
            records.append(row)
        elif a[0]=='OWNER':
            row['owners'].append({'kind':a[1],'name':a[2],'uid':a[3]})
        elif a[0]=='CONDITION':
            row['conditions'].append({'type':a[1],'status':a[2],'reason':blank(a[3]),'lastTransitionTime':blank(a[4])})
        elif a[0] in ('INIT','CONTAINER'):
            row['init' if a[0]=='INIT' else 'containers'].append({'name':a[1],'ready':a[2]=='true','restartCount':integer(a[3]),'state':'waiting' if a[4] else 'running' if a[5] else 'terminated' if a[6] or a[7] else 'unknown','waitingReason':blank(a[4]),'startedAt':blank(a[5]) or blank(a[8]),'terminatedReason':blank(a[6]),'exitCode':integer(a[7]),'finishedAt':blank(a[9])})
        elif a[0]!='END':
            raise ValueError('UNRECOGNIZED_PROJECTION_RECORD')
    assert len(records)<=32
    runners=[]; excluded=[]
    for row in records:
        if any(x['kind']=='EphemeralRunner' for x in row['owners']):
            assert row['name'].startswith('arc-arm64-runner-')
            row['selectorMatchesARM']=row['nodeSelectorArchitecture']=='arm64' and row['scaleSetLabel']=='arc-arm64'
            row['ready']=any(x['type']=='Ready' and x['status']=='True' for x in row['conditions'])
            row['initialized']=any(x['type']=='Initialized' and x['status']=='True' for x in row['conditions'])
            row['scheduled']=any(x['type']=='PodScheduled' and x['status']=='True' for x in row['conditions'])
