            excluded.append({'name':row['name'],'uid':row['uid'],'ownerKinds':[x['kind'] for x in row['owners']],'nodeSelectorArchitecture':row['nodeSelectorArchitecture'],'scaleSetLabel':row['scaleSetLabel']})
    gh=json.loads(inputs['github']['response']['stdout'])
    assert gh['completePage'] is True and gh['totalCount']==gh['returnedCount']<=100
    byname={r['name']:r for r in gh['runners']}
    assert len(byname)==len(gh['runners'])
    for row in runners:
        record=byname.get(row['name'])
        row['githubNameMatched']=record is not None
        row['githubStatus']=record.get('status') if record else None
        row['githubBusy']=record.get('busy') if record else None
    a=inputs['scaleSet']['response']['stdout'].rstrip('\n').split('\t')
    assert a[0]=='SET' and a[1]=='arc-arm64' and a[4]=='arc-arm64'
    scale={'name':a[1],'uid':a[2],'createdAt':a[3],'runnerScaleSetName':a[4],'minRunners':integer(a[5]),'maxRunners':integer(a[6]),'statusProjection':dict(zip(['currentRunners','pendingRunners','runningRunners','failedRunners','desiredRunners'],[integer(v) for v in a[7:12]]))}
